using JTradeERP.Application.Common.Security;using JTradeERP.Domain.Security;using MediatR;namespace JTradeERP.Application.Features.Billing.NumberSeries.UpdateNumberSeries;public static class UpdateNumberSeriesEndPoint{public static void Map(IEndpointRouteBuilder e)=>e.MapPut("/number-series/{id:guid}",async(Guid id,UpdateNumberSeriesCommand c,ISender s,CancellationToken ct)=>Results.Ok(await s.Send(c with{Id=id},ct))).RequirePermission("Admin.NumberSeries.Manage",Capability.CreateEdit);}
